import { useEffect, useState } from "react";
import api from "../api/axios";
import { useSocket } from "../context/SocketContext";

const NEXT_STATUS = {
  placed: "confirmed",
  confirmed: "preparing",
  preparing: "ready_for_pickup",
};
const NEXT_LABEL = {
  placed: "Confirm order",
  confirmed: "Start preparing",
  preparing: "Mark ready for pickup",
};

export default function RestaurantDashboard() {
  const { socket } = useSocket();
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [restaurant, setRestaurant] = useState(null);
  const [newItem, setNewItem] = useState({ name: "", price: "", category: "", description: "" });

  const loadAll = () => {
    api.get("/orders/mine").then(({ data }) => setOrders(data));
    api.get("/restaurants/mine").then(({ data }) => {
      setRestaurant(data.restaurant);
      setMenu(data.menu);
    });
  };

  useEffect(loadAll, []);

  useEffect(() => {
    if (!socket) return;
    const onNew = (order) => setOrders((prev) => [order, ...prev]);
    socket.on("order:new", onNew);
    return () => socket.off("order:new", onNew);
  }, [socket]);

  const advance = async (order) => {
    const status = NEXT_STATUS[order.status];
    if (!status) return;
    await api.put(`/orders/${order._id}/status`, { status });
    setOrders((prev) => prev.map((o) => (o._id === order._id ? { ...o, status } : o)));
  };

  const addMenuItem = async (e) => {
    e.preventDefault();
    const { data } = await api.post("/restaurants/mine/menu", {
      ...newItem,
      price: Number(newItem.price),
    });
    setMenu((prev) => [...prev, data]);
    setNewItem({ name: "", price: "", category: "", description: "" });
  };

  const activeOrders = orders.filter((o) => !["delivered", "cancelled"].includes(o.status));

  return (
    <div className="page">
      <div className="eyebrow">Restaurant dashboard</div>
      <h1>{restaurant?.name || "Your kitchen"}</h1>
      <hr className="route-rule" style={{ margin: "20px 0 28px" }} />

      <div style={{ display: "grid", gridTemplateColumns: "1.3fr 1fr", gap: 28 }}>
        <div>
          <h3 style={{ marginBottom: 14 }}>Live orders</h3>
          {activeOrders.length === 0 && <div className="empty-state">No active orders. New orders will appear here instantly.</div>}
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {activeOrders.map((o) => (
              <div key={o._id} className="card">
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <strong>#{o._id.slice(-6).toUpperCase()}</strong>
                  <span className="badge badge-live">{o.status.replace(/_/g, " ")}</span>
                </div>
                <ul style={{ margin: "10px 0", paddingLeft: 18, fontSize: 14, color: "var(--paper-dim)" }}>
                  {o.items.map((it, i) => (
                    <li key={i}>{it.quantity}× {it.name}</li>
                  ))}
                </ul>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <span style={{ fontFamily: "var(--font-mono)" }}>₹{o.totalAmount}</span>
                  {NEXT_STATUS[o.status] && (
                    <button className="btn btn-primary btn-sm" onClick={() => advance(o)}>
                      {NEXT_LABEL[o.status]}
                    </button>
                  )}
                  {o.status === "ready_for_pickup" && (
                    <span className="badge badge-idle">Waiting for agent pickup</span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div>
          <h3 style={{ marginBottom: 14 }}>Menu</h3>
          <form onSubmit={addMenuItem} className="card" style={{ marginBottom: 16 }}>
            <div className="field">
              <label>Item name</label>
              <input value={newItem.name} onChange={(e) => setNewItem({ ...newItem, name: e.target.value })} required />
            </div>
            <div className="field">
              <label>Price (₹)</label>
              <input type="number" value={newItem.price} onChange={(e) => setNewItem({ ...newItem, price: e.target.value })} required />
            </div>
            <div className="field">
              <label>Category</label>
              <input value={newItem.category} onChange={(e) => setNewItem({ ...newItem, category: e.target.value })} placeholder="e.g. Mains" />
            </div>
            <button className="btn btn-ghost btn-block">Add to menu</button>
          </form>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {menu.map((item) => (
              <div key={item._id} className="card" style={{ padding: 12, display: "flex", justifyContent: "space-between" }}>
                <span>{item.name}</span>
                <span style={{ fontFamily: "var(--font-mono)", color: "var(--signal-dim)" }}>₹{item.price}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
